css:
.cat-slider{-webkit-appearance:none;appearance:none;width:180px;height:20px;background:none;cursor:pointer}
.cat-slider::-webkit-slider-runnable-track{height:4px;border-radius:var(--cat-size-radius-pill);background:var(--cat-semantic-slider-track,rgba(0,0,0,.14))}
.cat-slider::-webkit-slider-thumb{-webkit-appearance:none;width:15px;height:15px;margin-top:-5.5px;border-radius:50%;background:#fff;border:.5px solid rgba(0,0,0,.15);box-shadow:0 1px 4px rgba(0,0,0,.28);transition:transform var(--cat-motion-fast) ease-out}
.cat-slider::-webkit-slider-thumb:hover{transform:scale(1.12)}
.cat-slider::-moz-range-track{height:4px;border-radius:var(--cat-size-radius-pill);background:rgba(0,0,0,.14)}
.cat-slider::-moz-range-thumb{width:15px;height:15px;border-radius:50%;background:#fff;border:.5px solid rgba(0,0,0,.15);box-shadow:0 1px 4px rgba(0,0,0,.28)}
.cat-slider.accent::-webkit-slider-runnable-track{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base))}
